package com.cdac.cssip.auth.config; import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(Exception.class)ResponseEntity<?>e(Exception e){HttpStatus s=e instanceof SecurityException?HttpStatus.FORBIDDEN:HttpStatus.BAD_REQUEST;return ResponseEntity.status(s).body(Map.of("timestamp",Instant.now().toString(),"status",s.value(),"error",e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()));}}